set res(_res: Response | undefined) {
  if (_res) {
    _res = createResponseInstance(_res.body, _res)
    const headers = this.#res ? this.#res.headers : this.#preparedHeaders
    if (headers) {
      // Capture both sides before modifying the new response. Set-Cookie is
      // handled separately because it can legitimately appear more than once.
      const incomingCookies = _res.headers.getSetCookie()
      const contextCookies = headers.getSetCookie()

      for (const [k, v] of headers.entries()) {
        if (k === 'content-type' || k === 'set-cookie') {
          continue
        }
        _res.headers.set(k, v)
      }

      if (contextCookies.length > 0) {
        _res.headers.delete('set-cookie')
        for (const cookie of contextCookies) {
          _res.headers.append('set-cookie', cookie)
        }
        // Keep cookies set by the new response too, without duplicating the
        // ones that were already carried by the context headers.
        for (const cookie of incomingCookies) {
          if (!contextCookies.includes(cookie)) {
            _res.headers.append('set-cookie', cookie)
          }
        }
      }
    }
  } else {
    // Discarding the response also discards headers staged by `c.header()`.
    this.#preparedHeaders = undefined
  }
  this.#res = _res
  this.finalized = true
}

